<?php
require __DIR__.'/app/bootstrap.php';
$u=current_user();if(!$u){header('Location:login.php');exit;}$d=db_load();
if(!user_can($d,$u,'audit.view')&&!user_can($d,$u,'pr.manage')){http_response_code(403);exit('Permission denied');}
$prId=(int)($_GET['pr_id']??0);$prs=$d['prs'];$logs=array_values(array_filter($d['audit'],function($a)use($prId){$actions=['pr_profile_updated','pr_attendance_checkin','pr_attendance_checkout','pr_status','pr_account_linked','pr_account_unlinked','pr_account_auto_linked'];if(!in_array((string)($a['action']??''),$actions,true))return false;return !$prId||(int)($a['pr_id']??0)===$prId;}));usort($logs,fn($a,$b)=>strcmp((string)($b['at']??''),(string)($a['at']??'')));
function prn(array $d,int $id):string{foreach($d['prs'] as $p)if((int)$p['id']===$id)return (string)$p['code'].' · '.(string)$p['name'];return 'PR #'.$id;}
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MR BAR — PR Activity</title><link rel="stylesheet" href="assets/admin.css?v=190"><style>.filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.timeline{display:grid;gap:10px}.event{display:grid;grid-template-columns:180px 1fr auto;gap:14px;padding:16px;border:1px solid #ffffff12;border-radius:16px;background:#ffffff04}.event code{color:#dcbcff}.fields{display:flex;gap:5px;flex-wrap:wrap}.fields span{padding:4px 7px;border:1px solid #8c4dff44;border-radius:8px;font-size:10px;color:#d9bcff}@media(max-width:760px){.event{grid-template-columns:1fr}}</style></head><body><main style="max-width:1180px;margin:auto;padding:26px"><header class="topbar"><div><p class="eyebrow">ADMIN / PR AUDIT</p><h1>PR Profile & Attendance Activity</h1><p>ติดตามการแก้ Profile และการเข้า/ออกงานของ PR</p></div><a class="logout" href="admin-manage.php">← Management</a><a class="logout" href="attendance-control.php">GPS / Evidence →</a></header><section class="panel"><form method="get" class="filters"><select name="pr_id"><option value="0">PR ทั้งหมด</option><?php foreach($prs as $p):?><option value="<?=$p['id']?>" <?=$prId===(int)$p['id']?'selected':''?>><?=h($p['code'].' · '.$p['name'])?></option><?php endforeach;?></select><button class="mini primary">Filter</button></form></section><section class="panel"><div class="timeline"><?php if(!$logs):?><p>ยังไม่มี Activity</p><?php endif;?><?php foreach(array_slice($logs,0,200) as $a):?><div class="event"><div><b><?=h(date('d/m/Y H:i:s',strtotime((string)$a['at'])))?></b><small style="display:block;color:#858ba6"><?=h(prn($d,(int)($a['pr_id']??0)))?></small></div><div><code><?=h((string)$a['action'])?></code><?php if(!empty($a['changed_fields'])):?><div class="fields"><?php foreach($a['changed_fields'] as $f):?><span><?=h((string)$f)?></span><?php endforeach;?></div><?php endif;?></div><div>by User #<?=intval($a['by']??$a['user_id']??0)?></div></div><?php endforeach;?></div></section></main></body></html>
